<?php
namespace App\Http\Controllers;
use App\Models\Router; use App\Services\RouterOsService; use Illuminate\Http\Request;
class RouterController extends Controller { public function index(){return view('routers.index',['routers'=>Router::latest()->get()]);} public function store(Request $r){$d=$r->validate(['name'=>'required|max:100','host'=>'required|max:255','port'=>'required|integer|min:1|max:65535','username'=>'required|max:100','password'=>'required','ssl'=>'nullable|boolean','enabled'=>'nullable|boolean','notes'=>'nullable']);Router::create($d);return back()->with('success','Router disimpan.');} public function update(Request $r,Router $router){$d=$r->validate(['name'=>'required|max:100','host'=>'required|max:255','port'=>'required|integer|min:1|max:65535','username'=>'required|max:100','password'=>'nullable','ssl'=>'nullable|boolean','enabled'=>'nullable|boolean','notes'=>'nullable']);if($d['password']==='')unset($d['password']);$router->update($d);return back()->with('success','Router diperbarui.');} public function test(Router $router,RouterOsService $api){$r=$api->testConnection($router);return back()->with($r['ok']?'success':'error',$r['ok']?'Koneksi berhasil. Identity/resource terbaca.':'Koneksi gagal: '.$r['error']);} public function destroy(Router $router){$router->delete();return back()->with('success','Router dihapus.');}}
